import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from divergingStacked ----
/**
 * Illustrative developer-experience survey: 16 statements rated on a 5 point Likert scale.
 * Values are percentages of respondents and sum to 100 per row. Synthetic, not a real survey.
 */
const RESPONSE_LEVELS = [
  'Strongly disagree',
  'Disagree',
  'Neutral',
  'Agree',
  'Strongly agree'
] as const;

type ResponseLevel = (typeof RESPONSE_LEVELS)[number];

type SurveyRow = { question: string } & Record<ResponseLevel, number>;

const surveyResponses: SurveyRow[] = [
  { question: 'Build times are acceptable', 'Strongly disagree': 18, Disagree: 27, Neutral: 20, Agree: 25, 'Strongly agree': 10 },
  { question: 'CI is reliable', 'Strongly disagree': 12, Disagree: 20, Neutral: 18, Agree: 34, 'Strongly agree': 16 },
  { question: 'Docs are easy to find', 'Strongly disagree': 15, Disagree: 24, Neutral: 21, Agree: 29, 'Strongly agree': 11 },
  { question: 'Code review is timely', 'Strongly disagree': 8, Disagree: 17, Neutral: 20, Agree: 38, 'Strongly agree': 17 },
  { question: 'On-call load is fair', 'Strongly disagree': 22, Disagree: 26, Neutral: 19, Agree: 23, 'Strongly agree': 10 },
  { question: 'The test suite is trustworthy', 'Strongly disagree': 14, Disagree: 22, Neutral: 20, Agree: 30, 'Strongly agree': 14 },
  { question: 'Deploys feel safe', 'Strongly disagree': 9, Disagree: 16, Neutral: 18, Agree: 38, 'Strongly agree': 19 },
  { question: 'Tooling stays out of the way', 'Strongly disagree': 11, Disagree: 19, Neutral: 22, Agree: 32, 'Strongly agree': 16 },
  { question: 'Postmortems change things', 'Strongly disagree': 6, Disagree: 12, Neutral: 17, Agree: 40, 'Strongly agree': 25 },
  { question: 'Sprint scope is realistic', 'Strongly disagree': 20, Disagree: 25, Neutral: 18, Agree: 26, 'Strongly agree': 11 },
  { question: 'Design specs are clear', 'Strongly disagree': 13, Disagree: 21, Neutral: 22, Agree: 31, 'Strongly agree': 13 },
  { question: 'Onboarding was smooth', 'Strongly disagree': 10, Disagree: 18, Neutral: 19, Agree: 36, 'Strongly agree': 17 },
  { question: 'Meetings are worth the time', 'Strongly disagree': 24, Disagree: 27, Neutral: 18, Agree: 22, 'Strongly agree': 9 },
  { question: 'Local setup is painless', 'Strongly disagree': 17, Disagree: 23, Neutral: 20, Agree: 28, 'Strongly agree': 12 },
  { question: 'Metrics answer my questions', 'Strongly disagree': 12, Disagree: 19, Neutral: 23, Agree: 33, 'Strongly agree': 13 },
  { question: 'I can ship without asking', 'Strongly disagree': 7, Disagree: 14, Neutral: 19, Agree: 39, 'Strongly agree': 21 }
];

/** One row per question, giving the percentage of responses at each of the five Likert levels. */
export type Data = {
  question: string;
  'Strongly disagree': number;
  Disagree: number;
  Neutral: number;
  Agree: number;
  'Strongly agree': number;
}[];

const MARGIN = { top: 30, right: 22, bottom: 56, left: 176 };
const ROW_HEIGHT = 24;
const LEGEND_MIN_SLOT = 108;

// Neutral straddles zero, so it takes one stack key per side but stays one legend entry.
const STACK_KEYS = [
  'Neutral−',
  'Disagree',
  'Strongly disagree',
  'Neutral+',
  'Agree',
  'Strongly agree'
] as const;

type StackKey = (typeof STACK_KEYS)[number];
type StackRow = { question: string } & Record<StackKey, number>;

const isNeutral = (key: StackKey) => key === 'Neutral−' || key === 'Neutral+';
const levelOf = (key: StackKey): ResponseLevel => (isNeutral(key) ? 'Neutral' : key);

const formatPercent = d3.format('.0%');
const formatTick = d3.format('+.0%');

export default function DivergingStackedBar({
  data = surveyResponses,
  width
}: {
  data?: Data;
  width: number;
}) {
  const innerHeight = data.length * ROW_HEIGHT;
  const height = innerHeight + MARGIN.top + MARGIN.bottom;
  const innerWidth = width - MARGIN.left - MARGIN.right;

  // Signed shares: disagreement negative, agreement positive, neutral split evenly across zero.
  const rows: StackRow[] = useMemo(
    () =>
      data
        .map((d) => ({
          question: d.question,
          'Strongly disagree': -d['Strongly disagree'] / 100,
          Disagree: -d.Disagree / 100,
          'Neutral−': -d.Neutral / 200,
          'Neutral+': d.Neutral / 200,
          Agree: d.Agree / 100,
          'Strongly agree': d['Strongly agree'] / 100
        }))
        .sort((a, b) => b.Agree + b['Strongly agree'] - (a.Agree + a['Strongly agree'])),
    [data]
  );

  const series: d3.Series<StackRow, StackKey>[] = useMemo(
    () =>
      d3
        .stack<StackRow, StackKey>()
        .keys([...STACK_KEYS])
        .value((d, key) => d[key])
        .offset(d3.stackOffsetDiverging)(rows),
    [rows]
  );

  const x = useMemo(() => {
    const low = d3.min(series, (s) => d3.min(s, (p) => p[0]) ?? 0) ?? 0;
    const high = d3.max(series, (s) => d3.max(s, (p) => p[1]) ?? 0) ?? 0;
    return d3.scaleLinear().domain([low, high]).range([0, innerWidth]);
  }, [series, innerWidth]);

  const y = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(rows.map((d) => d.question))
        .range([0, innerHeight])
        .padding(0.18),
    [rows, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleOrdinal<ResponseLevel, string>().domain(RESPONSE_LEVELS).range(d3.schemeRdYlBu[5]),
    []
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(2, Math.round(innerWidth / 90)))
        .map((v) => ({ value: formatTick(v), offset: x(v) })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  const zero = x(0);
  const legendSlot = innerWidth / RESPONSE_LEVELS.length;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Diverging stacked bar chart of Likert responses to 16 developer-experience statements, disagreement stacked left of zero and agreement right. Illustrative synthetic data, not a real survey.">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {xTicks.map((t) => (
            <line key={t.value} className="grid" x1={t.offset} x2={t.offset} y1={0} y2={innerHeight} />
          ))}
        </g>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        {series.map((s) => (
          <g key={s.key} fill={color(levelOf(s.key))}>
            {s.map((p) => (
              <rect
                key={p.data.question}
                x={x(p[0])}
                y={y(p.data.question) ?? 0}
                width={Math.max(0, x(p[1]) - x(p[0]))}
                height={y.bandwidth()}
              >
                <title>
                  {`${p.data.question}\n${levelOf(s.key)}: ${formatPercent(
                    Math.abs(p[1] - p[0]) * (isNeutral(s.key) ? 2 : 1)
                  )}`}
                </title>
              </rect>
            ))}
          </g>
        ))}

        {rows.map((d) => (
          <text
            key={d.question}
            x={-10}
            y={(y(d.question) ?? 0) + y.bandwidth() / 2}
            dy="0.32em"
            textAnchor="end"
            fill="var(--text)"
            fontSize={11}
          >
            {d.question}
          </text>
        ))}

        <line x1={zero} x2={zero} y1={0} y2={innerHeight} stroke="var(--line)" />

        {legendSlot >= LEGEND_MIN_SLOT && (
          <g fontSize={11} transform={`translate(0,${-MARGIN.top + 14})`}>
            {RESPONSE_LEVELS.map((level, i) => (
              <g key={level} transform={`translate(${i * legendSlot},0)`}>
                <rect y={-8} width={11} height={11} fill={color(level)} />
                <text x={17} dy="0.32em" fill="var(--text)">
                  {level}
                </text>
              </g>
            ))}
          </g>
        )}

        <text x={0} y={innerHeight + 44} fill="var(--muted)" fontSize={10}>
          Illustrative synthetic responses, not a real survey. Disagreement stacks left of zero,
          agreement right; neutral straddles it.
        </text>
      </g>
    </svg>
  );
}
